/**
 * BinaryHeap - Min-heap priority queue for A* pathfinding
 *
 * Min-heap priority queue for A* pathfinding.
 * Provides O(log n) push and pop operations.
 * Uses a score function to determine element priority.
 * Supports rescoring elements when their priority changes.
 *
 * **Usage**
 *
 * ```js
 * const heap = new BinaryHeap(node => node.f);
 * heap.push({ f: 10, cell: cellA });
 * heap.push({ f: 5, cell: cellB });
 * const min = heap.pop(); // { f: 5, cell: cellB }
 * ```
 *
 * @class BinaryHeap
 * @short Min-heap priority queue for A* pathfinding
 * @category Core
 * @private
 * @tags Heap, Priority Queue, A*
 */
export class BinaryHeap {
    /**
     * Create a new binary heap.
     *
     * @param {Function} scoreFunction - Function that returns numeric score for an element.
     */
    constructor(scoreFunction: Function);
    _content: any[];
    _scoreFunction: Function;
    /**
     * Get number of elements in the heap.
     *
     * @returns {number} Element count.
     */
    size(): number;
    /**
     * Check if heap is empty.
     *
     * @returns {boolean} True if empty.
     */
    isEmpty(): boolean;
    /**
     * Add element to the heap.
     *
     * @param {*} element - Element to add.
     */
    push(element: any): void;
    /**
     * Remove and return the minimum element.
     *
     * @returns {*} Element with lowest score, or undefined if empty.
     */
    pop(): any;
    /**
     * Update element position after its score changed.
     * Call this when you modify an element's score property.
     *
     * @param {*} element - Element to rescore.
     */
    rescoreElement(element: any): void;
    /**
     * Check if element exists in heap.
     *
     * @param {*} element - Element to find.
     * @returns {boolean} True if element exists.
     */
    contains(element: any): boolean;
    /**
     * Remove all elements from the heap.
     */
    clear(): void;
    /**
     * Bubble element up to maintain heap property.
     *
     * @param {number} n - Index of element to bubble.
     * @private
     */
    private _bubbleUp;
    /**
     * Sink element down to maintain heap property.
     *
     * @param {number} n - Index of element to sink.
     * @private
     */
    private _sinkDown;
}
